/* ---- sahipli sınıf yardımcıları ---- */
static void SurecCikti__birak(SurecCikti* p);
static SurecCikti SurecCikti__kopya(SurecCikti v);
static void SurecCikti__birak(SurecCikti* p) {
    if (!p) { return; }
    upp_metin_release(p->cikti); p->cikti = NULL;
}
static SurecCikti SurecCikti__kopya(SurecCikti v) {
    SurecCikti* p = &v;
    p->cikti = upp_metin_kopya(p->cikti);
    return v;
}
static void SurecCikti__ham_kopya(void* d, const void* s) { *(SurecCikti*)d = SurecCikti__kopya(*(const SurecCikti*)s); }
static void SurecCikti__ham_birak(void* p) { SurecCikti__birak((SurecCikti*)p); }
static const UppKolTur _upp_kt_SurecCikti = { sizeof(SurecCikti), SurecCikti__ham_kopya, SurecCikti__ham_birak };


